changeSet.sql:
-- The next version of group #3: the current one is closed and kept for the checks made with it CREATE TEMP TABLE new_version ON COMMIT DROP AS SELECT g.id AS previous_id, nextval('public.stop_factor_group_id_generator') AS id FROM stop_factors.stop_factor_group g WHERE COALESCE(g.root_id, g.id) = 3 AND g.valid_to IS NULL;
UPDATE stop_factors.stop_factor_group SET valid_to = now() WHERE id IN (SELECT previous_id FROM new_version);
INSERT INTO stop_factors.stop_factor_group (id, created_date, root_id, version_number, name, description, order_number, is_active, valid_from, change_reason) SELECT v.id, now(), COALESCE(g.root_id, g.id), g.version_number + 1, g.name, g.description, g.order_number, g.is_active, now(), 'Новые общие ограничения 2026' FROM new_version v JOIN stop_factors.stop_factor_group g ON g.id = v.previous_id;
-- Copies of every stop factor of the group with their conditions; general limits 2026: #11 rejects above 3, -- #12 above 7 CREATE TEMP TABLE new_factor ON COMMIT DROP AS SELECT s.previous_id, nextval('public.stop_factor_id_generator') AS id, s.group_id FROM (SELECT f.id AS previous_id, v.id AS group_id FROM stop_factors.stop_factor f JOIN new_version v ON v.previous_id = f.group_id ORDER BY f.order_number, f.id) s;
INSERT INTO stop_factors.stop_factor (id, created_date, name, description, is_active, order_number, group_id, metric_id, segment, params) SELECT n.id, now(), f.name, f.description, f.is_active, f.order_number, n.group_id, f.metric_id, f.segment, f.params FROM new_factor n JOIN stop_factors.stop_factor f ON f.id = n.previous_id;
INSERT INTO stop_factors.stop_factor_condition (id, created_date, stop_factor_id, result, operator, value, value_to, value_type) SELECT nextval('public.stop_factor_condition_id_generator'), now(), n.id, c.result, c.operator, CASE WHEN c.result = 'REJECTED' AND n.previous_id = 11 THEN '3' WHEN c.result = 'REJECTED' AND n.previous_id = 12 THEN '7' ELSE c.value END, c.value_to, c.value_type FROM new_factor n JOIN stop_factors.stop_factor_condition c ON c.stop_factor_id = n.previous_id;
INSERT INTO stop_factors.stop_factor_product (stop_factor_id, product_id) SELECT n.id, p.product_id FROM new_factor n JOIN stop_factors.stop_factor_product p ON p.stop_factor_id = n.previous_id;

rollback.sql:
CREATE TEMP TABLE removed_version ON COMMIT DROP AS
SELECT id, root_id, valid_from
FROM stop_factors.stop_factor_group
WHERE change_reason = 'Новые общие ограничения 2026' AND valid_to IS NULL;

CREATE TEMP TABLE removed_factor ON COMMIT DROP AS
SELECT f.id FROM stop_factors.stop_factor f JOIN removed_version r ON r.id = f.group_id;

DELETE FROM stop_factors.stop_factor_check WHERE stop_factor_id IN (SELECT id FROM removed_factor);
DELETE FROM stop_factors.stop_factor_condition WHERE stop_factor_id IN (SELECT id FROM removed_factor);
DELETE FROM stop_factors.stop_factor_product WHERE stop_factor_id IN (SELECT id FROM removed_factor);
DELETE FROM stop_factors.stop_factor WHERE id IN (SELECT id FROM removed_factor);
DELETE FROM stop_factors.stop_factor_group WHERE id IN (SELECT id FROM removed_version);

UPDATE stop_factors.stop_factor_group g
SET valid_to = NULL
FROM removed_version r
WHERE COALESCE(g.root_id, g.id) = r.root_id AND g.valid_to = r.valid_from;

changeSet.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM overdue_rule_product WHERE product_id IS NULL) THEN
        RAISE EXCEPTION 'Products of the requirements are not in public.product: %',
            (SELECT string_agg(name, ', ') FROM overdue_rule_product WHERE product_id IS NULL);
    END IF;
END $$;

-- The next version of group #5: the current one is closed and kept for the checks made with it CREATE TEMP TABLE new_version ON COMMIT DROP AS SELECT g.id AS previous_id, nextval('public.stop_factor_group_id_generator') AS id FROM stop_factors.stop_factor_group g WHERE COALESCE(g.root_id, g.id) = 5 AND g.valid_to IS NULL;
UPDATE stop_factors.stop_factor_group SET valid_to = now() WHERE id IN (SELECT previous_id FROM new_version);
INSERT INTO stop_factors.stop_factor_group (id, created_date, root_id, version_number, name, description, order_number, is_active, valid_from, change_reason) SELECT v.id, now(), COALESCE(g.root_id, g.id), g.version_number + 1, g.name, g.description, g.order_number, g.is_active, now(), 'Правила по просрочкам 2026' FROM new_version v JOIN stop_factors.stop_factor_group g ON g.id = v.previous_id;
-- The overdue history of the 2026 requirements, in the order and with the names of the requirements file CREATE TEMP TABLE overdue_rule ON COMMIT DROP AS SELECT nextval('public.stop_factor_id_generator') AS id, r.* FROM (VALUES -- order, segment, months from..to, max overdue days from..to, UNDERWRITER above, REJECTED above, name; -- REJECTED is count > REJECTED above, UNDERWRITER the RANGE up to it, NULL - no threshold ( 1, 'RETAIL', 1, 3, 1, 10, NULL, 5, 'Количество непрерывных просрочек за 1-3 месяца, где максимальная просрочка >= 1 и <= 10'), ( 2, 'RETAIL', 1, 3, 11, 20, 1, 2, 'Количество непрерывных просрочек за 1-3 месяца, где максимальная просрочка >= 11 и <= 20'), ( 3, 'RETAIL', 1, 3, 21, NULL, NULL, 0, 'Количество непрерывных просрочек за 1-3 месяца, где максимальная просрочка >= 21'), ( 4, 'RETAIL', 4, 6, 1, 10, NULL, 5, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 4 го по 6 месяц, где максимальная просрочка >= 1 и <= 10'), ( 5, 'RETAIL', 4, 6, 11, 20, 1, 2, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 4 го по 6 месяц, где максимальная просрочка >= 11 и <= 20'), ( 6, 'RETAIL', 4, 6, 21, NULL, NULL, 0, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 4 го по 6 месяц, где максимальная просрочка >= 21'), ( 7, 'RETAIL', 7, 12, 1, 5, NULL, NULL, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 7 го по 12 месяц, где максимальная просрочка >= 1 и <= 5'), ( 8, 'RETAIL', 7, 12, 6, 10, 5, 8, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 7 го по 12 месяц, где максимальная просрочка >= 6 и <= 10'), ( 9, 'RETAIL', 7, 12, 11, 20, 0, 1, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 7 го по 12 месяц, где максимальная просрочка >= 11 и <= 20'), (10, 'RETAIL', 7, 12, 21, NULL, NULL, 0, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 7 го по 12 месяц, где максимальная просрочка >= 21'), (11, 'RETAIL', 13, 24, 1, 10, NULL, NULL, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 13-го по 24-ый месяц, где максимальная просрочка >= 1 и <= 10'), (12, 'RETAIL', 13, 24, 11, 20, 7, 10, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 13-го по 24-ый месяц, где максимальная просрочка >= 11 и <= 20'), (13, 'RETAIL', 13, 24, 21, 30, 0, 1, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 13-го по 24-ый месяц, где максимальная просрочка >= 21 и <= 30'), (14, 'RETAIL', 13, 24, 31, NULL, NULL, 0, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 13-го по 24-ый месяц, где максимальная просрочка >= 31'), (15, NULL , 25, 36, 1, 30, NULL, NULL, 'Количество непрерывной просроченной задолженности c 25-го по 36-oй месяц, где максимальная просрочка >= 1 И <= 30'), (16, NULL , 25, 36, 31, 60, 0, 1, 'Количество непрерывной просроченной задолженности c 25-го по 36-oй месяц, где максимальная просрочка >= 31 и <= 60'), (17, NULL , 25, 36, 61, NULL, NULL, 0, 'Количество непрерывной просроченной задолженности c 25-го по 36-oй месяц, где максимальная просрочка >= 61'), (18, 'MSB' , 1, 3, 1, 10, 5, 10, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 1 го по 3 месяц, где максимальная просрочка >= 1 и <= 10'), (19, 'MSB' , 1, 3, 11, 20, 1, 2, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 1 го по 3 месяц, где максимальная просрочка >= 11 и <= 20'), (20, 'MSB' , 1, 3, 21, NULL, NULL, 0, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 1 го по 3 месяц, где максимальная просрочка >= 21'), (21, 'MSB' , 4, 6, 1, 10, 5, 10, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 4 го по 6 месяц, где максимальная просрочка >= 1 и <= 10'), (22, 'MSB' , 4, 6, 11, 20, 1, 2, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 4 го по 6 месяц, где максимальная просрочка >= 11 и <= 20'), (23, 'MSB' , 4, 6, 21, NULL, NULL, 0, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 4 го по 6 месяц, где максимальная просрочка >= 21'), (24, 'MSB' , 7, 12, 1, 10, NULL, NULL, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 7 го по 12 месяц, где максимальная просрочка >= 1 и <= 10'), (25, 'MSB' , 7, 12, 11, 20, 7, 10, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 7 го по 12 месяц, где максимальная просрочка >= 11 и <= 20'), (26, 'MSB' , 7, 12, 21, 30, 0, 1, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 7 го по 12 месяц, где максимальная просрочка >= 21 и <= 30'), (27, 'MSB' , 7, 12, 31, NULL, NULL, 0, 'Количество непрерывной просроченной задолженности по основному долгу и/или процентам с 7 го по 12 месяц, где максимальная просрочка >= 31') ) AS r (n, segment, period_from, period_to, min_days, max_days, underwriter_above, rejected_above, name) ORDER BY r.n;
INSERT INTO stop_factors.stop_factor (id, created_date, name, is_active, order_number, group_id, metric_id, segment, params) SELECT r.id, now(), r.name, true, r.n, v.id, 10, r.segment, jsonb_strip_nulls(jsonb_build_object('periodFromMonth', r.period_from, 'periodToMonth', r.period_to, 'minOverdueDays', r.min_days, 'maxOverdueDays', r.max_days)) FROM overdue_rule r CROSS JOIN new_version v ORDER BY r.n;
INSERT INTO stop_factors.stop_factor_condition (id, created_date, stop_factor_id, result, operator, value, value_to, value_type) SELECT nextval('public.stop_factor_condition_id_generator'), now(), r.id, c.result, c.operator, c.value, c.value_to, 'INTEGER' FROM overdue_rule r CROSS JOIN LATERAL (VALUES ('REJECTED', 'GT', r.rejected_above::text, NULL), ('UNDERWRITER', 'RANGE', r.underwriter_above::text, r.rejected_above::text)) AS c (result, operator, value, value_to) WHERE c.value IS NOT NULL ORDER BY r.n, c.result;
INSERT INTO stop_factors.stop_factor_product (stop_factor_id, product_id) SELECT r.id, p.product_id FROM overdue_rule r JOIN overdue_rule_product p ON p.segment = r.segment;

